SELECT "MulheresMil_1"."no_modalidade" AS "no_modalidade",   "MulheresMil_1"."nome_do_curso" AS "nome_do_curso",   SUM(CAST("MulheresMil_1"."Number_of_Records" AS BIGINT)) AS "sum_Number_of_Records_ok" FROM "MulheresMil_1" WHERE (("MulheresMil_1"."no_modalidade" = 'Pronatec Brasil sem Miséria') AND (NOT (("MulheresMil_1"."nome_da_sit_matricula__situacao_detalhada_" NOT IN ('', 'TRANSF_EXT', 'INTEGRALIZADA', 'FREQ_INIC_INSUF', 'TRANCADA', 'CONCLUÍDA', 'TRANSF_INT', 'EM_CURSO', 'REPROVADA', 'ABANDONO', 'CONFIRMADA', 'EM_DEPENDÊNCIA')) OR ("MulheresMil_1"."nome_da_sit_matricula__situacao_detalhada_" IS NULL))) AND (NOT ("MulheresMil_1"."situacao_da_turma" IN ('CANCELADA', 'CRIADA', 'PUBLICADA')))) GROUP BY "MulheresMil_1"."no_modalidade",   "MulheresMil_1"."nome_do_curso";
